def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, cells))
    return out


def _is_corner_line(cells):
    """True for an unbranched, filled L made from one row and one column."""
    pts = set(cells)
    if len(pts) < 5:
        return False
    minr, maxr = min(r for r, c in pts), max(r for r, c in pts)
    minc, maxc = min(c for r, c in pts), max(c for r, c in pts)
    for r in range(minr, maxr + 1):
        for c in range(minc, maxc + 1):
            expected = {(r, x) for x in range(minc, maxc + 1)} | {(y, c) for y in range(minr, maxr + 1)}
            if pts == expected:
                return True
    return False


def transform(grid):
    # A long corner-line object is the color key; recolor the largest other
    # connected foreground object to its color.
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid)
    keys = [(len(cells), color) for color, cells in comps
            if color != bg and _is_corner_line(cells)]
    if not keys:
        return [row[:] for row in grid]
    key_color = max(keys)[1]
    targets = [(len(cells), color, cells) for color, cells in comps
               if color != bg and color != key_color]
    if not targets:
        return [row[:] for row in grid]
    _, _, cells = max(targets, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for r, c in cells:
        out[r][c] = key_color
    return out
